    end

    subgraph DESP [DESPACHO - quien elige la ecuacion]
        DS_ANY["CUALQUIER BYTE por Bluetooth DISPARA UNA MEDIDA<br>gui.c:295 (activador O bufferIndex &gt; 0). Si no casa con ningun codigo,<br>mide y no contesta. Tambien '#', '@' o CR/LF."]
        DS_ST["PANTALLA: bufferPantalla[8] - ecuacionesCalibracion.c:73-130<br>Solo con el GATILLO (BOTON_INICIO, RE1; gui.c:294,311-315).<br>Resultado a la STONE (presentarDato, gui.c:235-257), NUNCA por Bluetooth.<br>0x09 NO EXISTE (salto de :108 a :112). 0x0E: sin ecuacion (:128-130)."]
        DS_STPERS["El color elegido en pantalla NO SE BORRA NUNCA:<br>borrarBuffer() esta vacia (uart_stone.c:32-35).<br>Tras el arranque bufferPantalla[8] = 0: el gatillo mide y no muestra nada."]
        DS_BT["BLUETOOTH: PRIMER BYTE de bufferData - ecuacionesCalibracion.c:137-198<br>1-6 intensas (:141-164), 7, 8, a-d opacas (:167-190),<br>e SIN ECUACION: devuelve la x (:191-193)."]
        DS_RESP["RESPUESTA ::&lt;n&gt; SIN TERMINADOR - conversionDatoEnviar :56-67<br>sprintf %u + '::' delante, sendUartStr, y pitido de 80 ms (gui.c:45-56).<br>El cliente cierra la respuesta por silencio."]
        DS_BAT["'9' BATERIA - gui.c:328-340, responde :&lt;n&gt;: (un solo ':' delante)<br>ROTO: parte de batteryVoltage ya reescalado a 0-99 en gui.c:349-350,<br>la lectura fresca esta comentada (:329-330), y nivel[2] (gui.c:267)<br>DESBORDA con cualquier valor de dos o mas cifras (gui.c:335)."]
        DS_DOBLE["GATILLO PULSADO + BYTE Bluetooth a la vez: se aplican DOS ecuaciones<br>seguidas, la de pantalla (gui.c:311-315) y la del byte (gui.c:325-327),<br>sobre la misma reflectivityValue. Con 'e' sale la de pantalla."]
        DS_ANY --> DS_BT --> DS_RESP
        DS_ANY --> DS_BAT
        DS_ST --> DS_STPERS
        DS_ST -.-> DS_DOBLE
        DS_BT -.-> DS_DOBLE
    end

